function step6_results_analysis()
%STEP6_RESULTS_ANALYSIS
% Step 6 - Results Analysis & Final Evaluation
%
% Loads the model comparison CSV generated by Step 4 and the
% backtest results MAT file generated by Step 5.
%
% The test period is NOT modified or re-optimized.
%
% Outputs:
%   - Model ranking
%   - Generalization analysis
%   - Strategy comparison
%   - Risk-return analysis
%   - Final figures
%   - Final summary MAT file

clc;
close all;

fprintf('\n============================================================\n');
fprintf(' [STEP 6] RESULTS ANALYSIS & FINAL EVALUATION\n');
fprintf('============================================================\n\n');

%% ============================================================
% 1. PATH SETUP
% ============================================================

thisFile = mfilename('fullpath');

if isempty(thisFile)
    srcDir = pwd;
else
    srcDir = fileparts(thisFile);
end

projectDir = fileparts(srcDir);

modelsDir  = fullfile(projectDir, 'results', 'models');
tablesDir  = fullfile(projectDir, 'results', 'tables');
figuresDir = fullfile(projectDir, 'results', 'figures');

if ~exist(modelsDir, 'dir')
    mkdir(modelsDir);
end

if ~exist(tablesDir, 'dir')
    mkdir(tablesDir);
end

if ~exist(figuresDir, 'dir')
    mkdir(figuresDir);
end

%% ============================================================
% 2. LOAD STEP 4 MODEL COMPARISON
% ============================================================

fprintf('-> Loading Step 4 model comparison results...\n');

modelCSV = fullfile( ...
    tablesDir, ...
    'model_comparison.csv');

modelMAT = fullfile( ...
    modelsDir, ...
    'model_comparison.mat');

if isfile(modelCSV)

    fprintf('   Loading CSV:\n');
    fprintf('   %s\n', modelCSV);

    modelTable = readtable(modelCSV);

elseif isfile(modelMAT)

    fprintf('   CSV not found. Loading MAT file:\n');
    fprintf('   %s\n', modelMAT);

    modelData = load(modelMAT);

    modelTable = extractModelTable(modelData);

else

    error('step6:modelResultsMissing', ...
        ['Neither model_comparison.csv nor model_comparison.mat ' ...
         'could be found.\nPlease run Step 4 first.']);

end

fprintf('   Model comparison loaded successfully.\n');

%% ============================================================
% 3. DISPLAY MODEL RESULTS
% ============================================================

fprintf('\n------------------------------------------------------------\n');
fprintf(' [MODEL RESULTS]\n');
fprintf('------------------------------------------------------------\n');

disp(modelTable);

%% ============================================================
% 4. IDENTIFY MODEL COLUMNS
% ============================================================

modelNames = getTableColumn( ...
    modelTable, ...
    {'Model','ModelName','model','modelName'});

validationRMSE = getTableColumnNumeric( ...
    modelTable, ...
    {'ValidationRMSE','Validation_RMSE','ValRMSE'});

validationMAE = getTableColumnNumeric( ...
    modelTable, ...
    {'ValidationMAE','Validation_MAE','ValMAE'});

validationR2 = getTableColumnNumeric( ...
    modelTable, ...
    {'ValidationR2','Validation_R2','ValR2'});

testRMSE = getTableColumnNumeric( ...
    modelTable, ...
    {'TestRMSE','Test_RMSE'});

testMAE = getTableColumnNumeric( ...
    modelTable, ...
    {'TestMAE','Test_MAE'});

testR2 = getTableColumnNumeric( ...
    modelTable, ...
    {'TestR2','Test_R2'});

%% ============================================================
% 5. SELECT BEST MODEL USING VALIDATION RMSE
% ============================================================

fprintf('\n============================================================\n');
fprintf(' MODEL SELECTION ANALYSIS\n');
fprintf('============================================================\n');

validRMSE = isfinite(validationRMSE);

if ~any(validRMSE)
    error('step6:noValidRMSE', ...
        'No valid validation RMSE values were found.');
end

tempRMSE = validationRMSE;
tempRMSE(~validRMSE) = Inf;

[bestValRMSE, bestIdx] = min(tempRMSE);

bestModelName = modelNames{bestIdx};

fprintf('\nSelection criterion: Validation RMSE\n');
fprintf('Best model: %s\n', bestModelName);
fprintf('Validation RMSE: %.6f\n', bestValRMSE);
fprintf('Test RMSE: %.6f\n', testRMSE(bestIdx));
fprintf('Test MAE : %.6f\n', testMAE(bestIdx));
fprintf('Test R2  : %.4f\n', testR2(bestIdx));

%% ============================================================
% 6. MODEL RANKING
% ============================================================

fprintf('\n------------------------------------------------------------\n');
fprintf(' [MODEL RANKING]\n');
fprintf('------------------------------------------------------------\n');

[~, order] = sort(tempRMSE, 'ascend');

Rank = (1:numel(order))';

RankedModel = modelNames(order);
RankedValidationRMSE = validationRMSE(order);
RankedValidationMAE = validationMAE(order);
RankedValidationR2 = validationR2(order);
RankedTestRMSE = testRMSE(order);
RankedTestMAE = testMAE(order);
RankedTestR2 = testR2(order);

rankTable = table( ...
    Rank, ...
    RankedModel, ...
    RankedValidationRMSE, ...
    RankedValidationMAE, ...
    RankedValidationR2, ...
    RankedTestRMSE, ...
    RankedTestMAE, ...
    RankedTestR2, ...
    'VariableNames', { ...
    'Rank', ...
    'Model', ...
    'ValidationRMSE', ...
    'ValidationMAE', ...
    'ValidationR2', ...
    'TestRMSE', ...
    'TestMAE', ...
    'TestR2'});

disp(rankTable);

rankFile = fullfile( ...
    tablesDir, ...
    'model_ranking.csv');

writetable(rankTable, rankFile);

fprintf('Saved: %s\n', rankFile);

%% ============================================================
% 7. GENERALIZATION ANALYSIS
% ============================================================

fprintf('\n============================================================\n');
fprintf(' MODEL GENERALIZATION ANALYSIS\n');
fprintf('============================================================\n');

generalizationGap = ...
    testRMSE - validationRMSE;

generalizationGapPct = ...
    100 * generalizationGap ./ ...
    max(abs(validationRMSE), eps);

generalizationTable = table( ...
    modelNames, ...
    validationRMSE, ...
    testRMSE, ...
    generalizationGap, ...
    generalizationGapPct, ...
    'VariableNames', { ...
    'Model', ...
    'ValidationRMSE', ...
    'TestRMSE', ...
    'GeneralizationGap', ...
    'GeneralizationGapPct'});

disp(generalizationTable);

generalizationFile = fullfile( ...
    tablesDir, ...
    'model_generalization.csv');

writetable( ...
    generalizationTable, ...
    generalizationFile);

fprintf('Saved: %s\n', generalizationFile);

%% ============================================================
% 8. LOAD STEP 5 BACKTEST RESULTS
% ============================================================

fprintf('\n============================================================\n');
fprintf(' TRADING STRATEGY ANALYSIS\n');
fprintf('============================================================\n');

backtestFile = fullfile( ...
    modelsDir, ...
    'backtest_results.mat');

if ~isfile(backtestFile)

    error('step6:backtestResultsMissing', ...
        ['backtest_results.mat not found.\n' ...
         'Please run Step 5 first.']);

end

fprintf('-> Loading Step 5 backtest results...\n');

backtestData = load(backtestFile);

fprintf('   Loaded successfully.\n');

%% ============================================================
% 9. EXTRACT BACKTEST TABLE
% ============================================================

if isfield(backtestData, 'comparisonTable')

    backtestTable = backtestData.comparisonTable;

else

    error('step6:backtestTableMissing', ...
        'comparisonTable was not found in backtest_results.mat.');

end

fprintf('\nBacktest comparison:\n\n');

disp(backtestTable);

%% ============================================================
% 10. EXTRACT STRATEGY METRICS
% ============================================================

strategyNames = getTableColumn( ...
    backtestTable, ...
    {'Strategy','StrategyName'});

finalCapital = getTableColumnNumeric( ...
    backtestTable, ...
    {'FinalCapital','Final_Capital'});

totalReturn = getTableColumnNumeric( ...
    backtestTable, ...
    {'TotalReturnPct','Total_Return_Pct'});

annualizedReturn = getTableColumnNumeric( ...
    backtestTable, ...
    {'AnnualizedReturnPct','Annualized_Return_Pct'});

sharpe = getTableColumnNumeric( ...
    backtestTable, ...
    {'SharpeRatio','Sharpe'});

sortino = getTableColumnNumeric( ...
    backtestTable, ...
    {'SortinoRatio','Sortino'});

maxDrawdown = getTableColumnNumeric( ...
    backtestTable, ...
    {'MaxDrawdownPct','Max_Drawdown_Pct'});

winRate = getTableColumnNumeric( ...
    backtestTable, ...
    {'WinRatePct','Win_Rate_Pct'});

tradeCount = getTableColumnNumeric( ...
    backtestTable, ...
    {'TradeCount','Trades'});

profitFactor = getTableColumnNumeric( ...
    backtestTable, ...
    {'ProfitFactor','Profit_Factor'});

%% ============================================================
% 11. IDENTIFY STRATEGY ROWS
% ============================================================

arIdx = find( ...
    contains(lower(strategyNames), 'ar(5)'), ...
    1);

sentimentIdx = find( ...
    contains(lower(strategyNames), 'sentiment'), ...
    1);

buyHoldIdx = find( ...
    contains(lower(strategyNames), 'buy'), ...
    1);

if isempty(arIdx)
    error('step6:arStrategyMissing', ...
        'AR(5) strategy not found in backtest results.');
end

if isempty(buyHoldIdx)
    error('step6:buyHoldMissing', ...
        'Buy & Hold benchmark not found in backtest results.');
end

if isempty(sentimentIdx)
    sentimentIdx = NaN;
end

%% ============================================================
% 12. DISPLAY MAIN PERFORMANCE
% ============================================================

fprintf('\n------------------------------------------------------------\n');
fprintf(' [TEST PERIOD PERFORMANCE]\n');
fprintf('------------------------------------------------------------\n');

fprintf('\nAR(5) Strategy:\n');
fprintf('   Final capital : $%.2f\n', ...
    finalCapital(arIdx));

fprintf('   Total return  : %.2f%%\n', ...
    totalReturn(arIdx));

fprintf('   Annual return : %.2f%%\n', ...
    annualizedReturn(arIdx));

fprintf('   Sharpe ratio  : %.4f\n', ...
    sharpe(arIdx));

fprintf('   Sortino ratio : %.4f\n', ...
    sortino(arIdx));

fprintf('   Max drawdown  : %.2f%%\n', ...
    maxDrawdown(arIdx));

fprintf('   Win rate      : %.2f%%\n', ...
    winRate(arIdx));

fprintf('   Trades        : %d\n', ...
    round(tradeCount(arIdx)));

fprintf('   Profit factor : %.4f\n', ...
    profitFactor(arIdx));

if ~isnan(sentimentIdx)

    fprintf('\nSentiment-Filtered AR(5):\n');

    fprintf('   Final capital : $%.2f\n', ...
        finalCapital(sentimentIdx));

    fprintf('   Total return  : %.2f%%\n', ...
        totalReturn(sentimentIdx));

    fprintf('   Annual return : %.2f%%\n', ...
        annualizedReturn(sentimentIdx));

    fprintf('   Sharpe ratio  : %.4f\n', ...
        sharpe(sentimentIdx));

    fprintf('   Sortino ratio : %.4f\n', ...
        sortino(sentimentIdx));

    fprintf('   Max drawdown  : %.2f%%\n', ...
        maxDrawdown(sentimentIdx));

    fprintf('   Win rate      : %.2f%%\n', ...
        winRate(sentimentIdx));

    fprintf('   Trades        : %d\n', ...
        round(tradeCount(sentimentIdx)));

end

fprintf('\nBuy & Hold:\n');

fprintf('   Final capital : $%.2f\n', ...
    finalCapital(buyHoldIdx));

fprintf('   Total return  : %.2f%%\n', ...
    totalReturn(buyHoldIdx));

fprintf('   Annual return : %.2f%%\n', ...
    annualizedReturn(buyHoldIdx));

fprintf('   Sharpe ratio  : %.4f\n', ...
    sharpe(buyHoldIdx));

fprintf('   Sortino ratio : %.4f\n', ...
    sortino(buyHoldIdx));

fprintf('   Max drawdown  : %.2f%%\n', ...
    maxDrawdown(buyHoldIdx));

%% ============================================================
% 13. AR(5) VS BUY & HOLD
% ============================================================

fprintf('\n============================================================\n');
fprintf(' AR(5) VS BUY & HOLD\n');
fprintf('============================================================\n');

returnDifference = ...
    totalReturn(arIdx) - totalReturn(buyHoldIdx);

sharpeDifference = ...
    sharpe(arIdx) - sharpe(buyHoldIdx);

drawdownDifference = ...
    maxDrawdown(arIdx) - maxDrawdown(buyHoldIdx);

fprintf('\nReturn difference:\n');
fprintf('   AR(5) - Buy & Hold = %.2f percentage points\n', ...
    returnDifference);

fprintf('\nSharpe difference:\n');
fprintf('   AR(5) - Buy & Hold = %.4f\n', ...
    sharpeDifference);

fprintf('\nMaximum drawdown difference:\n');
fprintf('   AR(5) - Buy & Hold = %.2f percentage points\n', ...
    drawdownDifference);

%% ============================================================
% 14. SENTIMENT FILTER ANALYSIS
% ============================================================

fprintf('\n============================================================\n');
fprintf(' SENTIMENT FILTER ANALYSIS\n');
fprintf('============================================================\n');

if ~isnan(sentimentIdx)

    sentimentReturnChange = ...
        totalReturn(sentimentIdx) - ...
        totalReturn(arIdx);

    sentimentSharpeChange = ...
        sharpe(sentimentIdx) - ...
        sharpe(arIdx);

    fprintf('\nWithout sentiment filter:\n');
    fprintf('   Return: %.2f%%\n', ...
        totalReturn(arIdx));

    fprintf('   Sharpe: %.4f\n', ...
        sharpe(arIdx));

    fprintf('\nWith sentiment filter:\n');
    fprintf('   Return: %.2f%%\n', ...
        totalReturn(sentimentIdx));

    fprintf('   Sharpe: %.4f\n', ...
        sharpe(sentimentIdx));

    fprintf('\nEffect of sentiment filter:\n');
    fprintf('   Return change: %.2f percentage points\n', ...
        sentimentReturnChange);

    fprintf('   Sharpe change: %.4f\n', ...
        sentimentSharpeChange);

    if sentimentReturnChange > 0

        fprintf('\nResult: sentiment filtering improved total return.\n');

    else

        fprintf('\nResult: sentiment filtering reduced total return.\n');

    end

end

%% ============================================================
% 15. RISK-RETURN TABLE
% ============================================================

fprintf('\n============================================================\n');
fprintf(' RISK-RETURN SUMMARY\n');
fprintf('============================================================\n');

riskReturnTable = table( ...
    strategyNames, ...
    finalCapital, ...
    totalReturn, ...
    annualizedReturn, ...
    sharpe, ...
    sortino, ...
    maxDrawdown, ...
    winRate, ...
    tradeCount, ...
    profitFactor, ...
    'VariableNames', { ...
    'Strategy', ...
    'FinalCapital', ...
    'TotalReturnPct', ...
    'AnnualizedReturnPct', ...
    'SharpeRatio', ...
    'SortinoRatio', ...
    'MaxDrawdownPct', ...
    'WinRatePct', ...
    'TradeCount', ...
    'ProfitFactor'});

disp(riskReturnTable);

riskReturnFile = fullfile( ...
    tablesDir, ...
    'risk_return_summary.csv');

writetable( ...
    riskReturnTable, ...
    riskReturnFile);

fprintf('Saved: %s\n', riskReturnFile);

%% ============================================================
% 16. MODEL RMSE FIGURE
% ============================================================

fprintf('\n-> Generating model RMSE comparison figure...\n');

figure( ...
    'Name', 'Model RMSE Comparison', ...
    'Color', 'w');

x = 1:numel(modelNames);

bar( ...
    x, ...
    [validationRMSE testRMSE]);

grid on;

xlabel('Model');
ylabel('RMSE');

title('Validation and Test RMSE Comparison');

set(gca, ...
    'XTick', x, ...
    'XTickLabel', modelNames);

xtickangle(30);

legend( ...
    'Validation RMSE', ...
    'Test RMSE', ...
    'Location', 'best');

modelRMSEFigure = fullfile( ...
    figuresDir, ...
    'final_model_rmse_comparison.png');

saveas(gcf, modelRMSEFigure);

close(gcf);

fprintf('Saved: %s\n', modelRMSEFigure);

%% ============================================================
% 17. STRATEGY RETURN FIGURE
% ============================================================

fprintf('-> Generating strategy return comparison...\n');

figure( ...
    'Name', 'Strategy Return Comparison', ...
    'Color', 'w');

bar(totalReturn);

grid on;

xlabel('Strategy');
ylabel('Total Return (%)');

title('Test Period Strategy Returns');

set(gca, ...
    'XTick', 1:numel(strategyNames), ...
    'XTickLabel', strategyNames);

xtickangle(20);

strategyReturnFigure = fullfile( ...
    figuresDir, ...
    'strategy_return_comparison.png');

saveas(gcf, strategyReturnFigure);

close(gcf);

fprintf('Saved: %s\n', strategyReturnFigure);

%% ============================================================
% 18. SHARPE FIGURE
% ============================================================

fprintf('-> Generating Sharpe ratio comparison...\n');

figure( ...
    'Name', 'Sharpe Ratio Comparison', ...
    'Color', 'w');

bar(sharpe);

grid on;

xlabel('Strategy');
ylabel('Sharpe Ratio');

title('Test Period Risk-Adjusted Performance');

set(gca, ...
    'XTick', 1:numel(strategyNames), ...
    'XTickLabel', strategyNames);

xtickangle(20);

sharpeFigure = fullfile( ...
    figuresDir, ...
    'strategy_sharpe_comparison.png');

saveas(gcf, sharpeFigure);

close(gcf);

fprintf('Saved: %s\n', sharpeFigure);

%% ============================================================
% 19. DRAWDOWN FIGURE
% ============================================================

fprintf('-> Generating maximum drawdown comparison...\n');

figure( ...
    'Name', 'Maximum Drawdown Comparison', ...
    'Color', 'w');

bar(abs(maxDrawdown));

grid on;

xlabel('Strategy');
ylabel('Maximum Drawdown (%)');

title('Test Period Maximum Drawdown');

set(gca, ...
    'XTick', 1:numel(strategyNames), ...
    'XTickLabel', strategyNames);

xtickangle(20);

drawdownFigure = fullfile( ...
    figuresDir, ...
    'strategy_drawdown_comparison.png');

saveas(gcf, drawdownFigure);

close(gcf);

fprintf('Saved: %s\n', drawdownFigure);

%% ============================================================
% 20. FINAL EQUITY CURVE
% ============================================================

fprintf('-> Generating final equity curve...\n');

if isfield(backtestData, 'arResult') && ...
        isfield(backtestData, 'buyHoldResult')

    arResult = backtestData.arResult;
    buyHoldResult = backtestData.buyHoldResult;

    figure( ...
        'Name', 'Final Equity Curve', ...
        'Color', 'w');

    plot( ...
        arResult.equity, ...
        'LineWidth', 1.5);

    hold on;

    plot( ...
        buyHoldResult.equity, ...
        'LineWidth', 1.5);

    if isfield(backtestData, 'sentimentResult')

        sentimentResult = ...
            backtestData.sentimentResult;

        plot( ...
            sentimentResult.equity, ...
            'LineWidth', 1.5);

        legend( ...
            'AR(5)', ...
            'Buy & Hold', ...
            'Sentiment-Filtered AR(5)', ...
            'Location', 'best');

    else

        legend( ...
            'AR(5)', ...
            'Buy & Hold', ...
            'Location', 'best');

    end

    grid on;

    xlabel('Test Period Day');
    ylabel('Portfolio Value ($)');

    title('Final Test Period Equity Curves');

    hold off;

    finalEquityFigure = fullfile( ...
        figuresDir, ...
        'final_equity_curve.png');

    saveas(gcf, finalEquityFigure);

    close(gcf);

    fprintf('Saved: %s\n', finalEquityFigure);

else

    finalEquityFigure = '';

    fprintf('Equity curve data unavailable.\n');

end

%% ============================================================
% 21. FINAL ANALYSIS TABLE
% ============================================================

fprintf('\n-> Saving final strategy analysis...\n');

finalAnalysisFile = fullfile( ...
    tablesDir, ...
    'final_strategy_analysis.csv');

writetable( ...
    riskReturnTable, ...
    finalAnalysisFile);

fprintf('Saved: %s\n', finalAnalysisFile);

%% ============================================================
% 22. CREATE FINAL SUMMARY
% ============================================================

finalSummary = struct();

finalSummary.bestModel = bestModelName;

finalSummary.bestValidationRMSE = ...
    bestValRMSE;

finalSummary.bestModelTestRMSE = ...
    testRMSE(bestIdx);

finalSummary.bestModelTestMAE = ...
    testMAE(bestIdx);

finalSummary.bestModelTestR2 = ...
    testR2(bestIdx);

finalSummary.AR5_TotalReturnPct = ...
    totalReturn(arIdx);

finalSummary.AR5_SharpeRatio = ...
    sharpe(arIdx);

finalSummary.AR5_MaxDrawdownPct = ...
    maxDrawdown(arIdx);

finalSummary.BuyHold_TotalReturnPct = ...
    totalReturn(buyHoldIdx);

finalSummary.BuyHold_SharpeRatio = ...
    sharpe(buyHoldIdx);

finalSummary.BuyHold_MaxDrawdownPct = ...
    maxDrawdown(buyHoldIdx);

if ~isnan(sentimentIdx)

    finalSummary.SentimentFiltered_TotalReturnPct = ...
        totalReturn(sentimentIdx);

    finalSummary.SentimentFiltered_SharpeRatio = ...
        sharpe(sentimentIdx);

    finalSummary.SentimentFiltered_MaxDrawdownPct = ...
        maxDrawdown(sentimentIdx);

else

    finalSummary.SentimentFiltered_TotalReturnPct = NaN;

    finalSummary.SentimentFiltered_SharpeRatio = NaN;

    finalSummary.SentimentFiltered_MaxDrawdownPct = NaN;

end

finalSummary.AR5_Outperformed_BuyHold = ...
    totalReturn(arIdx) > totalReturn(buyHoldIdx);

finalSummary.AR5_Higher_Sharpe_Than_BuyHold = ...
    sharpe(arIdx) > sharpe(buyHoldIdx);

finalSummary.AR5_Lower_Drawdown_Than_BuyHold = ...
    abs(maxDrawdown(arIdx)) < ...
    abs(maxDrawdown(buyHoldIdx));

%% ============================================================
% 23. FINAL RESEARCH CONCLUSION
% ============================================================

fprintf('\n============================================================\n');
fprintf(' RESEARCH CONCLUSION\n');
fprintf('============================================================\n');

fprintf('\n1. MODEL SELECTION\n');
fprintf('   AR(5) was selected using validation RMSE.\n');

fprintf('\n2. PREDICTIVE PERFORMANCE\n');
fprintf('   Validation RMSE: %.6f\n', ...
    bestValRMSE);

fprintf('   Test RMSE      : %.6f\n', ...
    testRMSE(bestIdx));

fprintf('   Test MAE       : %.6f\n', ...
    testMAE(bestIdx));

fprintf('   Test R2        : %.4f\n', ...
    testR2(bestIdx));

fprintf('\n3. TRADING PERFORMANCE\n');
fprintf('   AR(5) return   : %.2f%%\n', ...
    totalReturn(arIdx));

fprintf('   Buy & Hold     : %.2f%%\n', ...
    totalReturn(buyHoldIdx));

fprintf('\n4. RISK-ADJUSTED PERFORMANCE\n');
fprintf('   AR(5) Sharpe   : %.4f\n', ...
    sharpe(arIdx));

fprintf('   Buy & Hold     : %.4f\n', ...
    sharpe(buyHoldIdx));

fprintf('\n5. DRAWDOWN\n');
fprintf('   AR(5)          : %.2f%%\n', ...
    maxDrawdown(arIdx));

fprintf('   Buy & Hold     : %.2f%%\n', ...
    maxDrawdown(buyHoldIdx));

fprintf('\n6. SENTIMENT FILTER\n');

if ~isnan(sentimentIdx)

    fprintf('   Without filter : %.2f%%\n', ...
        totalReturn(arIdx));

    fprintf('   With filter    : %.2f%%\n', ...
        totalReturn(sentimentIdx));

    if totalReturn(sentimentIdx) > ...
            totalReturn(arIdx)

        fprintf('   The sentiment filter improved test return.\n');

    else

        fprintf('   The sentiment filter reduced test return.\n');

    end

end

fprintf('\n7. OVERALL FINDING\n');

if totalReturn(arIdx) > ...
        totalReturn(buyHoldIdx)

    fprintf('   AR(5) outperformed Buy & Hold in total return.\n');

else

    fprintf('   AR(5) did not outperform Buy & Hold in total return.\n');

end

if sharpe(arIdx) > ...
        sharpe(buyHoldIdx)

    fprintf('   AR(5) achieved a higher Sharpe ratio.\n');

else

    fprintf('   AR(5) did not achieve a higher Sharpe ratio.\n');

end

fprintf('\n   The test-period result is retained as an honest\n');
fprintf('   out-of-sample evaluation.\n');

%% ============================================================
% 24. SAVE FINAL MAT RESULTS
% ============================================================

fprintf('\n-> Saving final analysis results...\n');

finalResultsFile = fullfile( ...
    modelsDir, ...
    'final_results_analysis.mat');

save( ...
    finalResultsFile, ...
    'finalSummary', ...
    'modelTable', ...
    'rankTable', ...
    'generalizationTable', ...
    'riskReturnTable');

fprintf('Saved:\n');
fprintf('   %s\n', finalResultsFile);

%% ============================================================
% 25. FINAL OUTPUT
% ============================================================

fprintf('\n============================================================\n');
fprintf(' [STEP 6 COMPLETE]\n');
fprintf('============================================================\n');

fprintf('\nBest model:\n');
fprintf('   %s\n', bestModelName);

fprintf('\nBest validation RMSE:\n');
fprintf('   %.6f\n', bestValRMSE);

fprintf('\nBest model test RMSE:\n');
fprintf('   %.6f\n', testRMSE(bestIdx));

fprintf('\nAR(5) strategy test return:\n');
fprintf('   %.2f%%\n', totalReturn(arIdx));

fprintf('\nBuy & Hold test return:\n');
fprintf('   %.2f%%\n', totalReturn(buyHoldIdx));

fprintf('\nGenerated tables:\n');
fprintf('   %s\n', rankFile);
fprintf('   %s\n', generalizationFile);
fprintf('   %s\n', riskReturnFile);
fprintf('   %s\n', finalAnalysisFile);

fprintf('\nGenerated figures:\n');
fprintf('   %s\n', modelRMSEFigure);
fprintf('   %s\n', strategyReturnFigure);
fprintf('   %s\n', sharpeFigure);
fprintf('   %s\n', drawdownFigure);

if ~isempty(finalEquityFigure)
    fprintf('   %s\n', finalEquityFigure);
end

fprintf('\nFinal MAT file:\n');
fprintf('   %s\n', finalResultsFile);

fprintf('\n============================================================\n');
fprintf(' PROJECT PIPELINE COMPLETE\n');
fprintf('============================================================\n\n');

end


%% ============================================================
% HELPER: EXTRACT MODEL TABLE FROM MAT
% ============================================================

function T = extractModelTable(S)

fields = fieldnames(S);

T = [];

for i = 1:numel(fields)

    value = S.(fields{i});

    if istable(value)

        T = value;
        return;

    end
end

error('step6:noModelTable', ...
    ['No MATLAB table was found inside model_comparison.mat. ' ...
     'The Step 4 CSV should be used instead.']);

end


%% ============================================================
% HELPER: GET TABLE COLUMN
% ============================================================

function values = getTableColumn(T, candidates)

values = [];

names = T.Properties.VariableNames;

% Exact match
for i = 1:numel(candidates)

    idx = strcmpi(names, candidates{i});

    if any(idx)

        values = T.(names{find(idx,1)});
        break;

    end
end

% Fuzzy match
if isempty(values)

    for i = 1:numel(candidates)

        idx = contains( ...
            lower(names), ...
            lower(candidates{i}));

        if any(idx)

            values = T.(names{find(idx,1)});
            break;

        end
    end
end

if isempty(values)

    error('step6:missingTableColumn', ...
        'Required table column could not be found.');

end

% Convert to cell strings
if iscell(values)

    values = cellfun( ...
        @(x) char(string(x)), ...
        values, ...
        'UniformOutput', false);

elseif isstring(values)

    values = cellstr(values);

elseif ischar(values)

    values = cellstr(values);

elseif iscategorical(values)

    values = cellstr(values);

else

    values = cellstr(string(values));

end

values = values(:);

end


%% ============================================================
% HELPER: GET NUMERIC TABLE COLUMN
% ============================================================

function values = getTableColumnNumeric(T, candidates)

values = [];

names = T.Properties.VariableNames;

% Exact match
for i = 1:numel(candidates)

    idx = strcmpi(names, candidates{i});

    if any(idx)

        values = T.(names{find(idx,1)});
        break;

    end
end

% Fuzzy match
if isempty(values)

    for i = 1:numel(candidates)

        idx = contains( ...
            lower(names), ...
            lower(candidates{i}));

        if any(idx)

            values = T.(names{find(idx,1)});
            break;

        end
    end
end

if isempty(values)

    error('step6:missingNumericColumn', ...
        'Required numeric table column could not be found.');

end

if iscell(values)

    values = str2double(string(values));

elseif isstring(values) || ...
       ischar(values) || ...
       iscategorical(values)

    values = str2double(string(values));

else

    values = double(values);

end

values = values(:);

end